/* ---------------------------------------------------------
   PERSISTENCE — dados compartilhados entre a equipe
--------------------------------------------------------- */
const SHARED_POLL_MS = 15000;

function useSharedState(key, seedFn) {
  const [value, setValue] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const skipNextWrite = useRef(false);

  useEffect(() => {
    let cancelled = false;

    const fetchValue = async (isPoll) => {
      try {
        const res = await window.storage.get(key, true);
        if (cancelled) return;
        if (isPoll) skipNextWrite.current = true;
        setValue(res ? JSON.parse(res.value) : seedFn());
        setLoaded(true);
      } catch {
        if (!cancelled && !isPoll) {
          setValue(seedFn());
          setLoaded(true);
        }
      }
    };

    fetchValue(false);
    const interval = setInterval(() => fetchValue(true), SHARED_POLL_MS);

    // no celular o navegador pausa o setInterval quando o app vai pra segundo
    // plano (troca de app, tela bloqueada) -- sem isso, ao voltar o usuário
    // fica vendo dados velhos até dar refresh manual na página.
    const onVisible = () => { if (document.visibilityState === "visible") fetchValue(true); };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);

    return () => {
      cancelled = true;
      clearInterval(interval);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
    };
  }, [key]);

  useEffect(() => {
    if (!loaded) return;
    if (skipNextWrite.current) { skipNextWrite.current = false; return; }
    window.storage.set(key, JSON.stringify(value), true).catch(() => {});
  }, [value, loaded, key]);

  return [value, setValue, loaded];
}

