function Pill({ children, tone = "neutral" }) {
  const tones = {
    neutral: { bg: "#211F1B", color: C.textDim },
    gold: { bg: "rgba(201,162,39,0.14)", color: C.goldBright },
    green: { bg: "rgba(111,191,139,0.14)", color: C.green },
    red: { bg: "rgba(210,104,91,0.16)", color: C.red },
    amber: { bg: "rgba(217,164,65,0.16)", color: C.amber },
    blue: { bg: "rgba(123,155,176,0.16)", color: C.blue },
    violet: { bg: "rgba(183,158,234,0.16)", color: C.violet },
  };
  const t = tones[tone] || tones.neutral;
  return (
    <span className="px-2 py-1 rounded-md text-xs font-medium whitespace-nowrap"
      style={{ background: t.bg, color: t.color, fontFamily: "Inter" }}>
      {children}
    </span>
  );
}

