function ProfileModal({ user, onSave, onClose }) {
  const [fotoUrl, setFotoUrl] = useState(user.fotoUrl || "");
  const [aniversario, setAniversario] = useState(user.aniversario || "");
  const [telefone, setTelefone] = useState(user.telefone || "");
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const url = await uploadImagem(file);
      setFotoUrl(url);
    } catch {
      // silencioso — usuário pode tentar de novo
    } finally {
      setUploading(false);
    }
  };

  const salvar = async () => {
    setSaving(true);
    await onSave({ fotoUrl, aniversario, telefone });
    setSaving(false);
    onClose();
  };

  const iniciais = user.nome.split(" ").map((p) => p[0]).slice(0, 2).join("");

  return (
    <Modal title="Configurar perfil" onClose={onClose}>
      <div className="flex items-center gap-4 mb-4">
        <div className="w-16 h-16 rounded-full flex items-center justify-center text-lg font-semibold overflow-hidden"
          style={{ background: C.gold, color: "#141209", fontFamily: "Inter" }}>
          {fotoUrl ? <img src={fotoUrl} alt="" className="w-full h-full object-cover" /> : iniciais}
        </div>
        <div>
          <input type="file" accept="image/*" onChange={handleFile} className="text-xs" style={{ color: C.textDim, fontFamily: "Inter" }} />
          {uploading && <div className="text-xs mt-1" style={{ color: C.textFaint }}>Enviando...</div>}
        </div>
      </div>
      <Field label="Data de aniversário">
        <input type="date" style={inputStyle} value={aniversario} onChange={(e) => setAniversario(e.target.value)} />
      </Field>
      <Field label="Telefone">
        <input style={inputStyle} value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="(11) 99999-9999" />
      </Field>
      <PrimaryBtn onClick={salvar} disabled={saving || uploading}>{saving ? "Salvando..." : "Salvar perfil"}</PrimaryBtn>
    </Modal>
  );
}

function NotificationBell({ currentUser }) {
  const [notifs, setNotifs] = useState([]);
  const [open, setOpen] = useState(false);

  const fetchNotifs = () => {
    listNotifications(currentUser.id).then(setNotifs).catch(() => {});
  };

  useEffect(() => {
    fetchNotifs();
    const interval = setInterval(fetchNotifs, 20000);
    return () => clearInterval(interval);
  }, [currentUser.id]);

  const naoLidas = notifs.filter((n) => !n.lida).length;

  const abrir = () => {
    const proximoEstado = !open;
    setOpen(proximoEstado);
    if (proximoEstado && naoLidas > 0) {
      notifs.filter((n) => !n.lida).forEach((n) => markNotificationRead(n.id).catch(() => {}));
      setNotifs(notifs.map((n) => ({ ...n, lida: true })));
    }
  };

  return (
    <div className="relative">
      <button onClick={abrir} className="relative rounded-full flex items-center justify-center"
        style={{ width: 40, height: 40, background: C.surface, border: `1px solid ${C.border}`, color: C.textDim, boxShadow: "0 2px 8px rgba(0,0,0,0.35)" }}
        title="Notificações">
        <Bell size={18} />
        {naoLidas > 0 && (
          <span className="absolute -top-1 -right-1 rounded-full text-[9px] font-bold flex items-center justify-center"
            style={{ width: 16, height: 16, background: C.red, color: "#fff", border: `2px solid ${C.bg}` }}>
            {naoLidas > 9 ? "9+" : naoLidas}
          </span>
        )}
      </button>
      {open && (
        <div className="absolute z-20 rounded-xl overflow-hidden" style={{ top: "100%", right: 0, marginTop: 8, width: 300, background: C.surface, border: `1px solid ${C.border}`, maxHeight: 340, overflowY: "auto", boxShadow: "0 8px 24px rgba(0,0,0,0.4)" }}>
          <div className="px-4 py-3 text-xs font-semibold uppercase tracking-wide" style={{ color: C.textFaint, borderBottom: `1px solid ${C.borderSoft}` }}>
            Notificações
          </div>
          {notifs.length === 0 && <div className="px-4 py-4 text-xs" style={{ color: C.textFaint }}>Nenhuma notificação ainda.</div>}
          {notifs.map((n) => (
            <div key={n.id} className="px-4 py-3 text-xs" style={{ borderBottom: `1px solid ${C.borderSoft}` }}>
              <div style={{ color: C.text, fontFamily: "Inter" }}>
                {n.tipo === "tarefa"
                  ? <>Nova tarefa pra você: <span style={{ color: C.goldBright, fontWeight: 600 }}>{n.trecho}</span></>
                  : <><span style={{ color: C.goldBright, fontWeight: 600 }}>{n.autorNome}</span> te marcou: "{n.trecho}"</>}
              </div>
              <div style={{ color: C.textFaint, marginTop: 3 }}>
                {new Date(n.criadoEm).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

