function DemandasModule({ demandas, setDemandas, clientes, equipe, logActivity = () => {} }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ title: "", client: "", priority: "Normal", status: "A iniciar", date: "", responsavelId: "" });
  const [view, setView] = useState("lista");
  const [clienteFiltro, setClienteFiltro] = useState("");
  const groups = ["A iniciar", "Criando", "Enviar pra aprovacao", "Em aprovacao", "Alteracao", "Entregue"];

  const add = () => {
    if (!form.title.trim()) return;
    setDemandas([{ id: uid(), ...form }, ...demandas]);
    logActivity("Demandas", "criou", form.title);
    if (form.responsavelId) {
      createNotification({
        userId: form.responsavelId,
        tipo: "tarefa",
        autorNome: "",
        trecho: form.title,
      }).catch(() => {});
    }
    setForm({ title: "", client: "", priority: "Normal", status: "A iniciar", date: "", responsavelId: "" });
    setOpen(false);
  };
  const remove = (id) => {
    const d = demandas.find((x) => x.id === id);
    setDemandas(demandas.filter((d) => d.id !== id));
    if (d) logActivity("Demandas", "excluiu", d.title);
  };
  const cycle = (id) => {
    let novoStatus = "";
    setDemandas(demandas.map((d) => {
      if (d.id !== id) return d;
      const i = groups.indexOf(d.status);
      novoStatus = groups[(i + 1) % groups.length];
      return { ...d, status: novoStatus };
    }));
    const d = demandas.find((x) => x.id === id);
    if (d) logActivity("Demandas", "moveu", `${d.title} → ${statusLabel[novoStatus] || novoStatus}`);
  };

  const clientesComDemanda = [...new Set(demandas.map((d) => d.client).filter(Boolean))];
  const visiveis = clienteFiltro ? demandas.filter((d) => d.client === clienteFiltro) : demandas;

  return (
    <div>
      <ModuleHeader title="Demandas" sub={`${demandas.length} tarefas no total · ${demandas.filter(d => d.status === "Alteracao").length} em alteração`}
        right={<PrimaryBtn onClick={() => setOpen(true)}><Plus size={16} />Nova demanda</PrimaryBtn>} />

      <div className="flex items-center justify-between gap-3 mb-5 flex-wrap">
        <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg" style={{ background: C.bgSoft, border: `1px solid ${C.border}` }}>
          <Users size={14} color={C.textFaint} />
          <select value={clienteFiltro} onChange={(e) => setClienteFiltro(e.target.value)}
            className="text-xs bg-transparent outline-none" style={{ color: C.text, fontFamily: "Inter" }}>
            <option value="">Todos os clientes</option>
            {clientesComDemanda.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="flex items-center rounded-lg overflow-hidden" style={{ border: `1px solid ${C.border}` }}>
          <button onClick={() => setView("lista")} className="p-2" style={{ background: view === "lista" ? C.surfaceHover : "transparent", color: view === "lista" ? C.text : C.textFaint }} title="Lista">
            <List size={15} />
          </button>
          <button onClick={() => setView("quadro")} className="p-2" style={{ background: view === "quadro" ? C.surfaceHover : "transparent", color: view === "quadro" ? C.text : C.textFaint }} title="Quadro">
            <LayoutGrid size={15} />
          </button>
        </div>
      </div>

      {view === "lista" && (
        <div className="flex flex-col gap-6">
          {groups.map((g) => {
            const items = visiveis.filter((d) => d.status === g);
            if (items.length === 0) return null;
            return (
              <div key={g}>
                <div className="flex items-center gap-2 mb-3">
                  <Pill tone={statusTone[g]}>{statusLabel[g]}</Pill>
                  <span className="text-xs" style={{ color: C.textFaint }}>{items.length}</span>
                </div>
                <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${C.border}` }}>
                  {items.map((d, idx) => (
                    <div key={d.id} className="flex items-center justify-between px-4 py-3"
                      style={{ background: C.surface, borderTop: idx ? `1px solid ${C.borderSoft}` : "none" }}>
                      <button className="flex items-center gap-3 text-left flex-1" onClick={() => cycle(d.id)} title="Avançar status">
                        <Circle size={14} color={C.textFaint} />
                        <div>
                          <div className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{d.title}</div>
                          <div className="text-xs mt-0.5" style={{ color: C.textFaint }}>
                            {d.client}{d.responsavelId ? ` · ${equipe.find((u) => u.id === d.responsavelId)?.nome || ""}` : ""}
                          </div>
                        </div>
                      </button>
                      <div className="flex items-center gap-3">
                        <Pill tone={priorityTone[d.priority]}>{d.priority}</Pill>
                        <span className="text-xs" style={{ color: C.textFaint, minWidth: 44, textAlign: "right" }}>{d.date}</span>
                        <IconBtn onClick={() => remove(d.id)} title="Remover"><Trash2 size={14} /></IconBtn>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {view === "quadro" && (
        <div className="flex gap-4 overflow-x-auto thin-scroll pb-2">
          {groups.map((g) => {
            const items = visiveis.filter((d) => d.status === g);
            return (
              <div key={g} className="flex-shrink-0" style={{ width: 260 }}>
                <div className="flex items-center gap-2 mb-3">
                  <Pill tone={statusTone[g]}>{statusLabel[g]}</Pill>
                  <span className="text-xs" style={{ color: C.textFaint }}>{items.length}</span>
                </div>
                <div className="flex flex-col gap-2">
                  {items.length === 0 && <div className="text-xs rounded-lg p-3" style={{ color: C.textFaint, background: C.surface, border: `1px dashed ${C.border}` }}>Vazio</div>}
                  {items.map((d) => (
                    <button key={d.id} onClick={() => cycle(d.id)} title="Avançar status"
                      className="text-left rounded-lg p-3" style={{ background: C.surface, border: `1px solid ${C.border}` }}>
                      <div className="text-sm mb-1.5" style={{ color: C.text, fontFamily: "Inter" }}>{d.title}</div>
                      <div className="text-xs mb-2" style={{ color: C.textFaint }}>
                        {d.client}{d.responsavelId ? ` · ${equipe.find((u) => u.id === d.responsavelId)?.nome || ""}` : ""}
                      </div>
                      <div className="flex items-center justify-between">
                        <Pill tone={priorityTone[d.priority]}>{d.priority}</Pill>
                        <span className="text-xs" style={{ color: C.textFaint }}>{d.date}</span>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {open && (
        <Modal title="Nova demanda" onClose={() => setOpen(false)}>
          <Field label="Título"><input style={inputStyle} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Ex: Edição do teaser" /></Field>
          <Field label="Cliente">
            <select style={inputStyle} value={form.client} onChange={(e) => setForm({ ...form, client: e.target.value })}>
              <option value="">Selecionar cliente</option>
              {clientes.map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
            </select>
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Prioridade">
              <select style={inputStyle} value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })}>
                {["Urgente", "Alta", "Normal", "Baixa"].map((p) => <option key={p}>{p}</option>)}
              </select>
            </Field>
            <Field label="Data"><input style={inputStyle} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} placeholder="Ex: 30 ago" /></Field>
          </div>
          <Field label="Responsável (notifica a pessoa)">
            <select style={inputStyle} value={form.responsavelId} onChange={(e) => setForm({ ...form, responsavelId: e.target.value })}>
              <option value="">Sem responsável definido</option>
              {equipe.map((u) => <option key={u.id} value={u.id}>{u.nome}</option>)}
            </select>
          </Field>
          <PrimaryBtn onClick={add}><Plus size={16} />Adicionar</PrimaryBtn>
        </Modal>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   LEADS / CRM
--------------------------------------------------------- */
function LeadsModule({ leads, setLeads, clientes, setClientes, logActivity = () => {} }) {
  const [openNew, setOpenNew] = useState(false);
  const [selectedId, setSelectedId] = useState(null);
  const [noteText, setNoteText] = useState("");
  const [form, setForm] = useState({ nome: "", empresa: "", telefone: "", email: "", origem: "Instagram", valorEstimado: "", responsavel: "", temperatura: "Morno" });

  const selected = leads.find((l) => l.id === selectedId) || null;

  const pipelineAberto = leads
    .filter((l) => l.estagio !== "Fechado ganho" && l.estagio !== "Fechado perdido")
    .reduce((s, l) => s + Number(l.valorEstimado), 0);
  const ganhos = leads.filter((l) => l.estagio === "Fechado ganho");
  const perdidos = leads.filter((l) => l.estagio === "Fechado perdido");
  const ganhoValor = ganhos.reduce((s, l) => s + Number(l.valorEstimado), 0);
  const taxaConversao = (ganhos.length + perdidos.length) > 0
    ? Math.round((ganhos.length / (ganhos.length + perdidos.length)) * 100) : 0;
  const ativos = leads.filter((l) => l.estagio !== "Fechado ganho" && l.estagio !== "Fechado perdido").length;

  const addLead = () => {
    if (!form.nome.trim()) return;
    const novo = {
      id: uid(), ...form, valorEstimado: Number(form.valorEstimado) || 0,
      estagio: "Novo lead", criadoEm: new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }),
      notas: [],
    };
    setLeads([novo, ...leads]);
    logActivity("Leads", "cadastrou", novo.nome);
    setForm({ nome: "", empresa: "", telefone: "", email: "", origem: "Instagram", valorEstimado: "", responsavel: "", temperatura: "Morno" });
    setOpenNew(false);
  };

  const removeLead = (id) => {
    const l = leads.find((x) => x.id === id);
    setLeads(leads.filter((l) => l.id !== id));
    if (selectedId === id) setSelectedId(null);
    if (l) logActivity("Leads", "excluiu", l.nome);
  };

  const setEstagio = (id, estagio) => {
    setLeads(leads.map((l) => (l.id === id ? { ...l, estagio } : l)));
    const l = leads.find((x) => x.id === id);
    if (l) logActivity("Leads", "moveu", `${l.nome} → ${estagioLabel[estagio] || estagio}`);
  };
  const setTemperatura = (id, temperatura) => setLeads(leads.map((l) => (l.id === id ? { ...l, temperatura } : l)));

  const addNota = () => {
    if (!noteText.trim() || !selected) return;
    const nota = { id: uid(), texto: noteText, data: new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }) };
    setLeads(leads.map((l) => (l.id === selected.id ? { ...l, notas: [nota, ...l.notas] } : l)));
    setNoteText("");
  };

  const converterEmCliente = () => {
    if (!selected) return;
    setClientes([
      { id: uid(), name: selected.empresa || selected.nome, recorrencia: "Projeto pontual", servicos: [], status: "Ativo", equipeIds: [], documento: "", progress: { done: 0, total: 0 }, since: selected.criadoEm },
      ...clientes,
    ]);
    setLeads(leads.map((l) => (l.id === selected.id ? { ...l, convertido: true } : l)));
    logActivity("Leads", "converteu em cliente", selected.empresa || selected.nome);
  };

  return (
    <div>
      <ModuleHeader title="Leads" sub="Prospecção e atendimento de novos clientes"
        right={<PrimaryBtn onClick={() => setOpenNew(true)}><Plus size={16} />Novo lead</PrimaryBtn>} />

      <div className="flex gap-4 flex-wrap mb-6">
        <StatCard icon={Radar} label="Leads ativos" value={ativos} sub={`${leads.length} no total`} />
        <StatCard icon={TrendingUp} label="Pipeline aberto" value={brl(pipelineAberto)} />
        <StatCard icon={CheckCircle2} label="Ganho no período" value={brl(ganhoValor)} subColor={C.green} sub={`${ganhos.length} fechados`} />
        <StatCard icon={ArrowRight} label="Taxa de conversão" value={`${taxaConversao}%`} sub={`${ganhos.length} ganhos / ${perdidos.length} perdidos`} />
      </div>

      <div className="flex flex-col gap-6">
        {ESTAGIOS.map((est) => {
          const items = leads.filter((l) => l.estagio === est);
          if (items.length === 0) return null;
          return (
            <div key={est}>
              <div className="flex items-center gap-2 mb-3">
                <Pill tone={estagioTone[est]}>{estagioLabel[est]}</Pill>
                <span className="text-xs" style={{ color: C.textFaint }}>{items.length}</span>
              </div>
              <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${C.border}` }}>
                {items.map((l, idx) => (
                  <div key={l.id} className="flex items-center justify-between px-4 py-3"
                    style={{ background: C.surface, borderTop: idx ? `1px solid ${C.borderSoft}` : "none" }}>
                    <button className="flex items-center gap-3 text-left flex-1" onClick={() => setSelectedId(l.id)}>
                      <div>
                        <div className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>
                          {l.nome} {l.convertido && <span style={{ color: C.green }}>· já é cliente</span>}
                        </div>
                        <div className="text-xs mt-0.5" style={{ color: C.textFaint }}>
                          {l.empresa ? `${l.empresa} · ` : ""}{l.origem} · {l.responsavel}
                        </div>
                      </div>
                    </button>
                    <div className="flex items-center gap-3">
                      {l.temperatura && <Pill tone={temperaturaTone[l.temperatura]}>{l.temperatura}</Pill>}
                      <span className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{brl(l.valorEstimado)}</span>
                      <span className="text-xs" style={{ color: C.textFaint, minWidth: 44, textAlign: "right" }}>{l.criadoEm}</span>
                      <IconBtn onClick={() => removeLead(l.id)} title="Remover"><Trash2 size={14} /></IconBtn>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
        {leads.length === 0 && <div className="text-sm" style={{ color: C.textFaint }}>Nenhum lead ainda. Cadastre o primeiro contato acima.</div>}
      </div>

      {openNew && (
        <Modal title="Novo lead" onClose={() => setOpenNew(false)}>
          <Field label="Nome"><input style={inputStyle} value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} /></Field>
          <Field label="Empresa (se houver)"><input style={inputStyle} value={form.empresa} onChange={(e) => setForm({ ...form, empresa: e.target.value })} /></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Telefone"><input style={inputStyle} value={form.telefone} onChange={(e) => setForm({ ...form, telefone: e.target.value })} /></Field>
            <Field label="E-mail"><input style={inputStyle} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Origem">
              <select style={inputStyle} value={form.origem} onChange={(e) => setForm({ ...form, origem: e.target.value })}>
                {["Instagram", "Indicação", "Site", "WhatsApp", "Evento", "Outro"].map((o) => <option key={o}>{o}</option>)}
              </select>
            </Field>
            <Field label="Valor estimado (R$)"><input type="number" style={inputStyle} value={form.valorEstimado} onChange={(e) => setForm({ ...form, valorEstimado: e.target.value })} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Responsável"><input style={inputStyle} value={form.responsavel} onChange={(e) => setForm({ ...form, responsavel: e.target.value })} placeholder="Quem vai atender" /></Field>
            <Field label="Temperatura">
              <select style={inputStyle} value={form.temperatura} onChange={(e) => setForm({ ...form, temperatura: e.target.value })}>
                {TEMPERATURAS.map((t) => <option key={t}>{t}</option>)}
              </select>
            </Field>
          </div>
          <PrimaryBtn onClick={addLead}><Plus size={16} />Adicionar lead</PrimaryBtn>
        </Modal>
      )}

      {selected && (
        <Modal title={selected.nome} onClose={() => setSelectedId(null)}>
          <div className="flex flex-col gap-1.5 mb-4 text-sm" style={{ fontFamily: "Inter" }}>
            {selected.empresa && <div style={{ color: C.textDim }}>{selected.empresa}</div>}
            {selected.telefone && <div className="flex items-center gap-2" style={{ color: C.textDim }}><Phone size={13} />{selected.telefone}</div>}
            {selected.email && <div className="flex items-center gap-2" style={{ color: C.textDim }}><Mail size={13} />{selected.email}</div>}
            <div style={{ color: C.textFaint }}>Origem: {selected.origem} · Responsável: {selected.responsavel}</div>
            <div style={{ color: C.gold, fontWeight: 600 }}>{brl(selected.valorEstimado)}</div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <Field label="Estágio">
              <select style={inputStyle} value={selected.estagio} onChange={(e) => setEstagio(selected.id, e.target.value)}>
                {ESTAGIOS.map((e) => <option key={e} value={e}>{estagioLabel[e]}</option>)}
              </select>
            </Field>
            <Field label="Temperatura">
              <select style={inputStyle} value={selected.temperatura || "Morno"} onChange={(e) => setTemperatura(selected.id, e.target.value)}>
                {TEMPERATURAS.map((t) => <option key={t}>{t}</option>)}
              </select>
            </Field>
          </div>

          {selected.estagio === "Fechado ganho" && !selected.convertido && (
            <button onClick={converterEmCliente}
              className="w-full flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-semibold mb-4"
              style={{ background: "rgba(111,191,139,0.14)", color: C.green, fontFamily: "Inter" }}>
              <CheckCircle2 size={15} />Converter em cliente
            </button>
          )}

          <div className="mb-2 text-xs" style={{ color: C.textDim, fontFamily: "Inter" }}>Atendimento</div>
          <div className="flex gap-2 mb-3">
            <input style={{ ...inputStyle, flex: 1 }} placeholder="Registrar contato ou observação..."
              value={noteText} onChange={(e) => setNoteText(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addNota()} />
            <button onClick={addNota} className="px-3 rounded-lg" style={{ background: C.gold, color: "#141209" }}>
              <MessageSquare size={15} />
            </button>
          </div>
          <div className="flex flex-col gap-2 max-h-40 overflow-y-auto">
            {selected.notas.length === 0 && <div className="text-xs" style={{ color: C.textFaint }}>Nenhum registro ainda.</div>}
            {selected.notas.map((n) => (
              <div key={n.id} className="text-xs rounded-lg p-2.5" style={{ background: C.bgSoft, border: `1px solid ${C.borderSoft}` }}>
                <div style={{ color: C.text, fontFamily: "Inter" }}>{n.texto}</div>
                <div style={{ color: C.textFaint, marginTop: 3 }}>{n.data}</div>
              </div>
            ))}
          </div>
        </Modal>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   FINANCEIRO
--------------------------------------------------------- */
function FinanceiroModule({ financeiro, setFinanceiro, clientes = [], isMobile, logActivity = () => {} }) {
  const [open, setOpen] = useState(null); // 'entrada' | 'saida'
  const [form, setForm] = useState({ desc: "", client: "", category: "", date: "", value: "" });
  const [copiedId, setCopiedId] = useState(null);
  const recebido = financeiro.entradas.reduce((s, e) => s + Number(e.value), 0);
  const gasto = financeiro.saidas.reduce((s, e) => s + Number(e.value), 0);
  const saldo = recebido - gasto;
  const pct = Math.min(100, Math.round((recebido / financeiro.metaMes) * 100));
  const notasEmitidas = financeiro.entradas.filter((e) => e.notaEmitida).length;
  const notasPendentes = financeiro.entradas.length - notasEmitidas;

  const addEntry = () => {
    if (!form.desc.trim() || !form.value) return;
    const item = { id: uid(), desc: form.desc, date: form.date, value: Number(form.value), client: form.client, category: form.category, notaEmitida: false };
    if (open === "entrada") setFinanceiro({ ...financeiro, entradas: [item, ...financeiro.entradas] });
    else setFinanceiro({ ...financeiro, saidas: [item, ...financeiro.saidas] });
    logActivity("Financeiro", open === "entrada" ? "lançou entrada" : "lançou saída", `${form.desc} · ${brl(Number(form.value))}`);
    setForm({ desc: "", client: "", category: "", date: "", value: "" });
    setOpen(null);
  };
  const removeEntry = (list, id) => {
    const item = financeiro[list].find((i) => i.id === id);
    setFinanceiro({ ...financeiro, [list]: financeiro[list].filter((i) => i.id !== id) });
    if (item) logActivity("Financeiro", "excluiu", `${item.desc} · ${brl(Number(item.value))}`);
  };
  const toggleNota = (id) =>
    setFinanceiro({ ...financeiro, entradas: financeiro.entradas.map((e) => (e.id === id ? { ...e, notaEmitida: !e.notaEmitida } : e)) });
  const copyDocumento = (e) => {
    const cliente = clientes.find((c) => c.name === e.client);
    if (!cliente?.documento) return;
    navigator.clipboard?.writeText(cliente.documento).catch(() => {});
    setCopiedId(e.id);
    setTimeout(() => setCopiedId((id) => (id === e.id ? null : id)), 1500);
  };

  return (
    <div>
      <ModuleHeader title="Financeiro" sub="Fechamento do mês · agosto de 2026" />

      <div className="flex gap-4 flex-wrap mb-6">
        <StatCard icon={TrendingUp} label="Lucro do mês" value={brl(saldo)} sub={`${pct}% da meta de ${brl(financeiro.metaMes)}`} subColor={C.gold} />
        <StatCard icon={TrendingUp} label="Recebido" value={brl(recebido)} />
        <StatCard icon={TrendingDown} label="Despesas" value={brl(gasto)} subColor={C.red} />
        <StatCard icon={Wallet} label="Saldo em caixa" value={brl(saldo)} />
        <StatCard icon={Receipt} label="Notas fiscais" value={`${notasEmitidas}/${financeiro.entradas.length}`} sub={`${notasPendentes} pendente${notasPendentes === 1 ? "" : "s"}`} subColor={notasPendentes ? C.red : C.green} />
      </div>

      <div className="grid gap-5" style={{ gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr" }}>
        <div className="rounded-xl p-5" style={{ background: C.surface, border: `1px solid ${C.border}` }}>
          <div className="flex items-center justify-between mb-4">
            <div className="text-sm" style={{ color: C.textDim, fontFamily: "Inter" }}>Entradas ({financeiro.entradas.length})</div>
            <button onClick={() => setOpen("entrada")} style={{ color: C.gold }}><Plus size={16} /></button>
          </div>
          <div className="flex flex-col gap-1">
            {financeiro.entradas.map((e) => {
              const cliente = clientes.find((c) => c.name === e.client);
              return (
                <div key={e.id} className="flex items-center justify-between py-2.5" style={{ borderBottom: `1px solid ${C.borderSoft}` }}>
                  <div className="min-w-0">
                    <div className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{e.desc}</div>
                    <div className="text-xs mt-0.5" style={{ color: C.textFaint }}>{e.client} · {e.date}</div>
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0">
                    <span className="text-sm font-medium mr-1" style={{ color: C.green, fontFamily: "Inter" }}>+{brl(e.value)}</span>
                    <IconBtn onClick={() => toggleNota(e.id)} title={e.notaEmitida ? "Nota fiscal emitida" : "Marcar nota fiscal como emitida"}>
                      <Receipt size={13} color={e.notaEmitida ? C.green : C.textFaint} style={{ opacity: e.notaEmitida ? 1 : 0.5 }} />
                    </IconBtn>
                    {cliente?.documento && (
                      <IconBtn onClick={() => copyDocumento(e)} title={copiedId === e.id ? "CPF/CNPJ copiado!" : `Copiar CPF/CNPJ (${cliente.documento})`}>
                        <Copy size={13} color={copiedId === e.id ? C.green : undefined} />
                      </IconBtn>
                    )}
                    <IconBtn onClick={() => removeEntry("entradas", e.id)}><Trash2 size={13} /></IconBtn>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="rounded-xl p-5" style={{ background: C.surface, border: `1px solid ${C.border}` }}>
          <div className="flex items-center justify-between mb-4">
            <div className="text-sm" style={{ color: C.textDim, fontFamily: "Inter" }}>Saídas ({financeiro.saidas.length})</div>
            <button onClick={() => setOpen("saida")} style={{ color: C.gold }}><Plus size={16} /></button>
          </div>
          <div className="flex flex-col gap-1">
            {financeiro.saidas.map((e) => (
              <div key={e.id} className="flex items-center justify-between py-2.5" style={{ borderBottom: `1px solid ${C.borderSoft}` }}>
                <div>
                  <div className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{e.desc}</div>
                  <div className="text-xs mt-0.5" style={{ color: C.textFaint }}>{e.category} · {e.date}</div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium" style={{ color: C.red, fontFamily: "Inter" }}>-{brl(e.value)}</span>
                  <IconBtn onClick={() => removeEntry("saidas", e.id)}><Trash2 size={13} /></IconBtn>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {open && (
        <Modal title={open === "entrada" ? "Nova entrada" : "Nova saída"} onClose={() => setOpen(null)}>
          <Field label="Descrição"><input style={inputStyle} value={form.desc} onChange={(e) => setForm({ ...form, desc: e.target.value })} /></Field>
          {open === "entrada"
            ? <Field label="Cliente"><input style={inputStyle} value={form.client} onChange={(e) => setForm({ ...form, client: e.target.value })} /></Field>
            : <Field label="Categoria"><input style={inputStyle} value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></Field>}
          <div className="grid grid-cols-2 gap-3">
            <Field label="Data"><input style={inputStyle} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} placeholder="dd/mm" /></Field>
            <Field label="Valor (R$)"><input type="number" style={inputStyle} value={form.value} onChange={(e) => setForm({ ...form, value: e.target.value })} /></Field>
          </div>
          <PrimaryBtn onClick={addEntry}><Plus size={16} />Adicionar</PrimaryBtn>
        </Modal>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   CONTRATOS
--------------------------------------------------------- */
function SectionLabel({ children }) {
  return (
    <div className="text-[11px] uppercase tracking-wide mt-5 mb-2 pb-1.5" style={{ color: C.textFaint, fontFamily: "Inter", fontWeight: 600, borderBottom: `1px solid ${C.borderSoft}` }}>
      {children}
    </div>
  );
}

const defaultMomento = (i, total) => {
  if (total <= 1) return "à vista";
  if (i === 0) return "no início dos serviços";
  if (i === total - 1) return "na conclusão da entrega";
  return `${i + 1}ª parcela`;
};

const emptyContratoForm = () => ({
  titulo: "", cliente: "", tipoDocumento: "CNPJ", documento: "",
  representante: "", cpfRepresentante: "", endereco: "",
  tipo: "Casamento", escopo: "", prazo: "",
  valor: "", formaPagamento: "Pix", numParcelas: 1, momentos: ["à vista"],
  vigenciaMeses: "", foro: "",
  status: "Rascunho",
});

const buildContractText = (form) => {
  const valorTotal = Number(form.valor) || 0;
  const n = Math.max(1, Number(form.numParcelas) || 1);
  const valorParcela = valorTotal / n;
  const momentos = form.momentos && form.momentos.length === n
    ? form.momentos
    : Array.from({ length: n }, (_, i) => defaultMomento(i, n));
  const linhasParcelas = n === 1
    ? [`- Pagamento único de ${brl(valorTotal)}, ${momentos[0] || "à vista"}.`]
    : momentos.map((m, i) => `- Parcela ${i + 1}: ${brl(valorParcela)} — ${m || "a combinar"}.`);

  return [
    "CONTRATO DE PRESTAÇÃO DE SERVIÇOS AUDIOVISUAIS",
    "",
    `CONTRATANTE: ${form.cliente || "[nome do cliente]"}${form.documento ? `, inscrito(a) no ${form.tipoDocumento || "CPF/CNPJ"} nº ${form.documento}` : ""}${form.endereco ? `, residente e domiciliado(a) em ${form.endereco}` : ""}.`,
    form.representante ? `Representante legal: ${form.representante}${form.cpfRepresentante ? ` (CPF nº ${form.cpfRepresentante})` : ""}.` : "",
    "CONTRATADA: DieselFilms Produções Audiovisuais.",
    "",
    "CLÁUSULA 1ª — DO OBJETO",
    `O presente contrato tem como objeto a prestação de serviços de ${(form.tipo || "").toLowerCase()} pela CONTRATADA à CONTRATANTE, compreendendo: ${form.escopo || "[descreva o escopo do serviço]"}.`,
    "",
    "CLÁUSULA 2ª — DO PRAZO",
    `A entrega dos materiais contratados ocorrerá em até ${form.prazo || "[prazo a combinar]"}, contados a partir da assinatura deste contrato ou da data do evento, o que for aplicável.`,
    "",
    "CLÁUSULA 3ª — DO VALOR E FORMA DE PAGAMENTO",
    `Pelos serviços descritos, a CONTRATANTE pagará à CONTRATADA o valor total de ${brl(valorTotal)}, via ${form.formaPagamento || "[forma de pagamento]"}, da seguinte forma:`,
    ...linhasParcelas,
    "",
    "CLÁUSULA 4ª — DA VIGÊNCIA E DO FORO",
    `O presente contrato vigora por ${form.vigenciaMeses || "[vigência]"} meses a partir de sua assinatura. Fica eleito o foro da comarca de ${form.foro || "[cidade]"} para dirimir quaisquer controvérsias oriundas deste instrumento.`,
    "",
    "CLÁUSULA 5ª — DAS DISPOSIÇÕES GERAIS",
    "Este documento é um rascunho gerado automaticamente pelo DieselFilms OS e deve ser revisado antes de qualquer assinatura formal.",
    "",
    "____________________________",
    "CONTRATANTE",
    "",
    "____________________________",
    "CONTRATADA — DieselFilms",
  ].join("\n");
};

const buildContractHtml = (form) => buildContractText(form).split("\n").map((line) => {
  if (!line.trim()) return `<p style="margin:0 0 10px">&nbsp;</p>`;
  if (line === "CONTRATO DE PRESTAÇÃO DE SERVIÇOS AUDIOVISUAIS") return `<p style="font-weight:700;font-size:15px;margin:0 0 14px">${line}</p>`;
  if (/^CLÁUSULA/.test(line)) return `<p style="font-weight:700;margin:14px 0 6px">${line}</p>`;
  if (line.startsWith("- ")) return `<p style="margin:0 0 4px 16px">${line}</p>`;
  return `<p style="margin:0 0 4px">${line}</p>`;
}).join("");

const baixarContratoDoc = (titulo, html) => {
  const conteudo = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"></head><body style="font-family:Calibri,Arial,sans-serif;font-size:13px;color:#1a1a1a;">${html}</body></html>`;
  const blob = new Blob([conteudo], { type: "application/msword" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${(titulo || "contrato").trim().replace(/[^\w\-]+/g, "_") || "contrato"}.doc`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
};

function ContratosModule({ contratos, setContratos, clientes = [], financeiro, setFinanceiro, isMobile, logActivity = () => {} }) {
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyContratoForm());
  const [copiedId, setCopiedId] = useState(null);
  const [docTouched, setDocTouched] = useState(false);
  const [previewVisible, setPreviewVisible] = useState(true);
  const docRef = useRef(null);
  const initRef = useRef(null);
  const totalMes = contratos.reduce((s, c) => s + Number(c.valor), 0);

  const resetForm = () => { setForm(emptyContratoForm()); setEditingId(null); };
  const startNew = () => { resetForm(); setDocTouched(false); setPreviewVisible(!isMobile); setOpen(true); };
  const startEdit = (c) => {
    const n = Math.max(1, Number(c.numParcelas) || 1);
    setForm({
      titulo: c.titulo, cliente: c.cliente, tipoDocumento: c.tipoDocumento || "CNPJ", documento: c.documento || "",
      representante: c.representante || "", cpfRepresentante: c.cpfRepresentante || "", endereco: c.endereco || "",
      tipo: c.tipo, escopo: c.escopo || "", prazo: c.prazo || "",
      valor: String(c.valor), formaPagamento: c.formaPagamento || "Pix",
      numParcelas: n, momentos: (c.momentos && c.momentos.length === n) ? c.momentos : Array.from({ length: n }, (_, i) => defaultMomento(i, n)),
      vigenciaMeses: c.vigenciaMeses || "", foro: c.foro || "",
      status: c.status,
    });
    setEditingId(c.id);
    setDocTouched(true);
    setPreviewVisible(!isMobile);
    setOpen(true);
  };

  const onClienteChange = (v) => {
    const match = clientes.find((cl) => cl.name.toLowerCase() === v.toLowerCase());
    setForm((f) => ({ ...f, cliente: v, documento: !f.documento && match?.documento ? match.documento : f.documento }));
  };

  const alterarParcelas = (delta) => {
    setForm((f) => {
      const n = Math.max(1, Math.min(12, (f.numParcelas || 1) + delta));
      const momentos = Array.from({ length: n }, (_, i) => f.momentos[i] || defaultMomento(i, n));
      return { ...f, numParcelas: n, momentos };
    });
  };
  const atualizarMomento = (i, v) => setForm((f) => ({ ...f, momentos: f.momentos.map((m, idx) => (idx === i ? v : m)) }));

  // injeta o conteudo inicial do documento (uma vez por abertura do modal)
  useEffect(() => {
    if (!open) { initRef.current = null; return; }
    const key = editingId || "new";
    if (initRef.current === key) return;
    initRef.current = key;
    const contratoAtual = editingId ? contratos.find((c) => c.id === editingId) : null;
    const html = contratoAtual?.corpoHtml || buildContractHtml(form);
    requestAnimationFrame(() => { if (docRef.current) docRef.current.innerHTML = html; });
  }, [open, editingId]);

  // mantem a previa sincronizada com os campos ate o usuario editar o texto na mao
  useEffect(() => {
    if (!open || docTouched || !docRef.current) return;
    docRef.current.innerHTML = buildContractHtml(form);
  }, [form, open, docTouched]);

  const regenerarPrevia = () => {
    setDocTouched(false);
    if (docRef.current) docRef.current.innerHTML = buildContractHtml(form);
  };

  const remove = (id) => {
    const c = contratos.find((x) => x.id === id);
    setContratos(contratos.filter((c) => c.id !== id));
    if (c) logActivity("Contratos", "excluiu", c.titulo);
  };

  const copyContract = (c) => {
    navigator.clipboard?.writeText(buildContractText(c)).catch(() => {});
    setCopiedId(c.id);
    setTimeout(() => setCopiedId((id) => (id === c.id ? null : id)), 1500);
  };

  const baixar = () => {
    const html = docRef.current ? docRef.current.innerHTML : buildContractHtml(form);
    baixarContratoDoc(form.titulo, html);
  };

  const gerarESalvar = () => {
    if (!form.titulo.trim()) return;
    const corpoHtml = docRef.current ? docRef.current.innerHTML : buildContractHtml(form);
    const id = editingId || uid();
    const payload = { ...form, valor: Number(form.valor) || 0, corpoHtml };
    if (editingId) {
      setContratos(contratos.map((c) => (c.id === editingId ? { ...c, ...payload } : c)));
      logActivity("Contratos", "editou", payload.titulo);
    } else {
      setContratos([{ id, ...payload }, ...contratos]);
      logActivity("Contratos", "gerou", payload.titulo);
    }
    if (financeiro && setFinanceiro) {
      const hoje = new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
      const jaExiste = financeiro.entradas.some((e) => e.contratoId === id);
      const base = { desc: payload.titulo, client: payload.cliente, value: payload.valor, contratoId: id };
      const novasEntradas = jaExiste
        ? financeiro.entradas.map((e) => (e.contratoId === id ? { ...e, ...base } : e))
        : [{ id: uid(), date: hoje, notaEmitida: false, ...base }, ...financeiro.entradas];
      setFinanceiro({ ...financeiro, entradas: novasEntradas });
    }
    resetForm();
    setOpen(false);
  };

  return (
    <div>
      <ModuleHeader title="Contratos" sub={`${contratos.length} contratos · ${brl(totalMes)} em valor total`}
        right={<PrimaryBtn onClick={startNew}><Plus size={16} />Novo contrato</PrimaryBtn>} />

      <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${C.border}` }}>
        {contratos.length === 0 && <div className="p-6 text-sm" style={{ color: C.textFaint, background: C.surface }}>Nenhum contrato ainda.</div>}
        {contratos.map((c, idx) => (
          <div key={c.id} className="flex items-center justify-between px-5 py-4 flex-wrap gap-3"
            style={{ background: C.surface, borderTop: idx ? `1px solid ${C.borderSoft}` : "none" }}>
            <div className="flex items-center gap-3">
              <FileText size={16} color={C.textFaint} />
              <div>
                <div className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{c.titulo}</div>
                <div className="text-xs mt-0.5" style={{ color: C.textFaint }}>{c.cliente} · {c.tipo}</div>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <span className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{brl(c.valor)}</span>
              <Pill tone={contratoTone[c.status]}>{c.status}</Pill>
              <IconBtn onClick={() => copyContract(c)} title={copiedId === c.id ? "Copiado!" : "Copiar texto do contrato"}>
                <Copy size={14} color={copiedId === c.id ? C.green : undefined} />
              </IconBtn>
              <IconBtn onClick={() => startEdit(c)} title="Editar"><Pencil size={14} /></IconBtn>
              <IconBtn onClick={() => remove(c.id)} title="Remover"><Trash2 size={14} /></IconBtn>
            </div>
          </div>
        ))}
      </div>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: "rgba(0,0,0,0.65)" }}>
          <div className="flex flex-col rounded-xl" style={{ width: "94vw", maxWidth: 1300, height: "90vh", background: C.surface, border: `1px solid ${C.border}` }}>
            <div className="flex items-center justify-between px-6 py-4" style={{ borderBottom: `1px solid ${C.borderSoft}` }}>
              <h3 style={{ fontFamily: "Fraunces", color: C.text }} className="text-lg font-medium">
                {editingId ? "Editar contrato" : "Novo contrato"}
              </h3>
              <div className="flex items-center gap-3">
                <button onClick={() => setPreviewVisible(!previewVisible)}
                  className="text-xs px-3 py-1.5 rounded-lg" style={{ color: C.textDim, border: `1px solid ${C.border}`, fontFamily: "Inter" }}>
                  {previewVisible ? "Ocultar prévia" : "Mostrar prévia"}
                </button>
                <button onClick={() => { setOpen(false); resetForm(); }} style={{ color: C.textFaint }}><X size={18} /></button>
              </div>
            </div>

            <div className={isMobile ? "flex-1 flex flex-col gap-0 min-h-0 overflow-y-auto thin-scroll" : "flex-1 flex gap-0 min-h-0"}>
              <div className={isMobile ? "px-6 py-5" : "thin-scroll overflow-y-auto px-6 py-5"} style={{ width: isMobile ? "100%" : (previewVisible ? 420 : "100%"), flexShrink: 0 }}>
                <div className="grid grid-cols-2 gap-3">
                  <Field label="Modelo de contrato">
                    <select style={inputStyle} value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })}>
                      {["Casamento", "Comercial", "Evento", "Ensaio"].map((t) => <option key={t}>{t}</option>)}
                    </select>
                  </Field>
                  <Field label="Cliente (autofill)">
                    <input style={inputStyle} list="contrato-clientes" value={form.cliente} onChange={(e) => onClienteChange(e.target.value)} placeholder="Em branco / sem cliente" />
                    <datalist id="contrato-clientes">
                      {clientes.map((cl) => <option key={cl.id} value={cl.name} />)}
                    </datalist>
                  </Field>
                </div>

                <SectionLabel>Contratante</SectionLabel>
                <Field label="Título do contrato"><input style={inputStyle} value={form.titulo} onChange={(e) => setForm({ ...form, titulo: e.target.value })} placeholder="Ex: Cobertura de casamento completa" /></Field>
                <div className="grid grid-cols-2 gap-3">
                  <Field label="Tipo de documento">
                    <select style={inputStyle} value={form.tipoDocumento} onChange={(e) => setForm({ ...form, tipoDocumento: e.target.value })}>
                      <option>CPF</option>
                      <option>CNPJ</option>
                    </select>
                  </Field>
                  <Field label="Número do documento"><input style={inputStyle} placeholder="Ex: 00.000.000/0001-00" value={form.documento} onChange={(e) => setForm({ ...form, documento: e.target.value })} /></Field>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <Field label="Representante (quem assina)"><input style={inputStyle} value={form.representante} onChange={(e) => setForm({ ...form, representante: e.target.value })} /></Field>
                  <Field label="CPF do representante"><input style={inputStyle} value={form.cpfRepresentante} onChange={(e) => setForm({ ...form, cpfRepresentante: e.target.value })} /></Field>
                </div>
                <Field label="Endereço completo">
                  <textarea style={{ ...inputStyle, height: 52, resize: "vertical" }} value={form.endereco} onChange={(e) => setForm({ ...form, endereco: e.target.value })} />
                </Field>

                <SectionLabel>Objeto e serviços</SectionLabel>
                <Field label="Serviços (o que será entregue)">
                  <textarea style={{ ...inputStyle, height: 72, resize: "vertical" }} placeholder="Ex: filmagem da cerimônia e festa, edição de teaser e filme completo"
                    value={form.escopo} onChange={(e) => setForm({ ...form, escopo: e.target.value })} />
                </Field>
                <Field label="Prazo de desenvolvimento"><input style={inputStyle} placeholder="Ex: 20 a 25 dias úteis" value={form.prazo} onChange={(e) => setForm({ ...form, prazo: e.target.value })} /></Field>

                <SectionLabel>Honorários</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <Field label="Valor total (R$)"><input type="number" style={inputStyle} value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} /></Field>
                  <Field label="Forma de pagamento">
                    <select style={inputStyle} value={form.formaPagamento} onChange={(e) => setForm({ ...form, formaPagamento: e.target.value })}>
                      {["Pix", "Cartão", "Boleto", "Transferência"].map((f) => <option key={f}>{f}</option>)}
                    </select>
                  </Field>
                </div>
                <Field label="Parcelamento">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="text-sm" style={{ color: C.text, fontFamily: "Inter" }}>{form.numParcelas} parcela{form.numParcelas > 1 ? "s" : ""}</span>
                    <div className="flex items-center rounded-lg overflow-hidden" style={{ border: `1px solid ${C.border}` }}>
                      <button type="button" onClick={() => alterarParcelas(-1)} className="w-7 h-7 flex items-center justify-center" style={{ color: C.textDim }}>−</button>
                      <button type="button" onClick={() => alterarParcelas(1)} className="w-7 h-7 flex items-center justify-center" style={{ color: C.textDim, borderLeft: `1px solid ${C.border}` }}>+</button>
                    </div>
                  </div>
                  <div className="flex flex-col gap-2">
                    {form.momentos.map((m, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <span className="text-xs whitespace-nowrap px-2 py-1.5 rounded-md" style={{ background: C.bgSoft, border: `1px solid ${C.border}`, color: C.goldBright, fontFamily: "Inter" }}>
                          {brl((Number(form.valor) || 0) / form.numParcelas)}
                        </span>
                        <input style={{ ...inputStyle, flex: 1 }} value={m} onChange={(e) => atualizarMomento(i, e.target.value)} placeholder="Ex: no início dos serviços" />
                      </div>
                    ))}
                  </div>
                  <div className="text-[11px] mt-1.5" style={{ color: C.textFaint, fontFamily: "Inter" }}>Os valores são divididos automaticamente a partir do valor total.</div>
                </Field>

                <SectionLabel>Vigência e foro</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <Field label="Vigência (meses)"><input type="number" style={inputStyle} value={form.vigenciaMeses} onChange={(e) => setForm({ ...form, vigenciaMeses: e.target.value })} /></Field>
                  <Field label="Foro (cidade)"><input style={inputStyle} value={form.foro} onChange={(e) => setForm({ ...form, foro: e.target.value })} /></Field>
                </div>

                <Field label="Status">
                  <select style={inputStyle} value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })}>
                    {["Rascunho", "Enviado", "Assinado"].map((s) => <option key={s}>{s}</option>)}
                  </select>
                </Field>
                {docTouched && (
                  <button onClick={regenerarPrevia} className="text-xs mt-1" style={{ color: C.goldBright, fontFamily: "Inter" }}>
                    ↻ atualizar prévia com os campos
                  </button>
                )}
              </div>

              {previewVisible && (
                <div className={isMobile ? "px-6 py-5" : "flex-1 thin-scroll overflow-y-auto px-6 py-5"} style={{ borderLeft: isMobile ? "none" : `1px solid ${C.borderSoft}`, borderTop: isMobile ? `1px solid ${C.borderSoft}` : "none" }}>
                  <div className="text-xs uppercase tracking-wide mb-3" style={{ color: C.textFaint, fontFamily: "Inter" }}>Pré-visualização · clique no texto para editar</div>
                  <div ref={docRef} contentEditable suppressContentEditableWarning
                    onInput={() => setDocTouched(true)}
                    className="rounded-lg p-6 text-sm outline-none"
                    style={{ background: C.bgSoft, border: `1px solid ${C.border}`, color: C.text, fontFamily: "Inter", lineHeight: 1.6, minHeight: 400 }} />
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-3 px-6 py-4 flex-wrap" style={{ borderTop: `1px solid ${C.borderSoft}` }}>
              <button onClick={baixar} className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium"
                style={{ color: C.textDim, border: `1px solid ${C.border}`, fontFamily: "Inter" }}>
                <Download size={15} />Baixar
              </button>
              <PrimaryBtn onClick={gerarESalvar}>
                <Plus size={16} />Gerar e salvar no mês
              </PrimaryBtn>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

